import queue, threading, time
class FakeVhal:
    def __init__(s): s.props = {"HVAC_TEMPERATURE_SET": 22.0}; s.subs = []
    def subscribe(s, cb): s.subs.append(cb)
    def inject(s, name, val):
        old = s.props.get(name); s.props[name] = val
        if old != val:                       # ON_CHANGE: 값이 바뀔 때만 알린다
            for cb in s.subs: cb(name, val)
v = FakeVhal(); q = queue.Queue(); v.subscribe(lambda n, x: q.put((n, x)))
def expect(name, val, timeout=1.0):
    t0 = time.monotonic()
    while time.monotonic() - t0 < timeout:
        try: n, x = q.get(timeout=0.05)
        except queue.Empty: continue
        if (n, x) == (name, val): return "OK %s=%s" % (name, val)
    return "FAIL %s=%s 이벤트 없음 (%.1fs 초과)" % (name, val, timeout)
threading.Timer(0.2, v.inject, ("HVAC_TEMPERATURE_SET", 24.5)).start()
print(expect("HVAC_TEMPERATURE_SET", 24.5))
v.inject("HVAC_TEMPERATURE_SET", 24.5)       # 같은 값 → 알림 없음
print(expect("HVAC_TEMPERATURE_SET", 24.5, timeout=0.3))
# OK HVAC_TEMPERATURE_SET=24.5
# FAIL HVAC_TEMPERATURE_SET=24.5 이벤트 없음 (0.3s 초과)
